children.rule_json:
{
  "step": 1,
  "fetch_mode": "browser",
  "target": "div.download_link",
  "link_selector": "a#downloadButton",
  "attr": "href",
  "browser_option":{
    "headless": false,
    "actions":[
        {
          "type": "wait_for_selector",
          "selector": "button#btn-main:not(.disable):not([disabled]), a#btn-main, button#btn-main, a.btn-main, button.btn-main",
          "timeout_ms": 45000
        },
        {
          "type": "click",
          "selector": "button#btn-main:not(.disable):not([disabled]), a#btn-main, button#btn-main, a.btn-main, button.btn-main",
          "wait_after_ms": 3000,
          "no_wait_after": true
        },
        {
          "type": "wait_for_load",
          "state": "domcontentloaded",
          "timeout_ms": 15000,
          "optional": true
        },
        {
          "type": "wait_for_selector",
          "selector": "button#btn-main:not(.disable):not([disabled]), a#btn-main, button#btn-main, a.btn-main, button.btn-main",
          "timeout_ms": 20000,
          "optional": true
        },
        {
          "type": "click",
          "selector": "button#btn-main:not(.disable):not([disabled]), a#btn-main, button#btn-main, a.btn-main, button.btn-main",
          "wait_after_ms": 3000,
          "no_wait_after": true,
          "optional": true
        },
        {
          "type": "sleep",
          "duration_ms": 5000
        }
    ],
  }
}
